const MONEY_RE = /£\s?\d|\d\s?%|\bper cent\b/i;
const OLD_RE = /\bprevious\b|\bpast (tax )?years?\b|\brates between\b|\bfrom april 20[01]\d\b/i;

function htmlBlocks(markup) {
