    let text, kind;
    if (blockTag === 'tr') { text = cells.some((c) => c !== '–') ? cells.join(' | ') : ''; kind = 'row'; }
    else { text = cleanText(buf.join(''), 2000); kind = { h2: 'heading', h3: 'heading', h4: 'heading', li: 'item' }[blockTag] || 'para'; }
